CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS otp (email TEXT PRIMARY KEY, code_hash TEXT NOT NULL, salt TEXT NOT NULL, expires INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS records (user_id INTEGER NOT NULL, id TEXT NOT NULL, type TEXT, amount REAL, cat TEXT, pay TEXT, cur TEXT, date TEXT, note TEXT, updated_at INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, srv_ts INTEGER NOT NULL, PRIMARY KEY (user_id, id));
CREATE INDEX IF NOT EXISTS idx_records_sync ON records(user_id, srv_ts);
CREATE TABLE IF NOT EXISTS settings (user_id INTEGER PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rl (k TEXT PRIMARY KEY, w INTEGER NOT NULL, c INTEGER NOT NULL);
